def dfs(graph, start):
    visited = []
    stack = [start]

    while stack:
        node = stack.pop()
        if node not in visited:
            visited.append(node)
            neighbors = graph.get(node, [])
            stack.extend(neighbors[::-1])  # Reverse to maintain DFS order

    return visited

