def dfs(graph, start):
    visited = []
    stack = [start]

    while stack:
        node = stack.pop()
        if node not in visited:
            visited.append(node)
            neighbors = graph.get(node, [])
            for neighbor in reversed(neighbors):
                stack.append(neighbor)

    return visited
```

